import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0005: 为什么依赖图由 Core Engine 协调","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0005-why-core-coordinates-the-graph.md","filePath":"zh/adr/ADR-0005-why-core-coordinates-the-graph.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0005-why-core-coordinates-the-graph.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0005-为什么依赖图由-core-engine-协调" tabindex="-1">ADR-0005: 为什么依赖图由 Core Engine 协调 <a class="header-anchor" href="#adr-0005-为什么依赖图由-core-engine-协调" aria-label="Permalink to “ADR-0005: 为什么依赖图由 Core Engine 协调”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/recovery-engine.md §6，ADR-0004</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>图有了，谁驱动？若各资源/插件自行判断&quot;我的依赖好了没有&quot;并自行恢复， 并发下必然出现两个资源同时修同一个依赖、恢复顺序竞态、互不知情的重复重启。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>恢复编排唯一归属 Core Engine：每个 tick 按拓扑序探测；恢复执行前重查依赖健康 （§3.6）；每个资源一把恢复互斥（同一资源绝不并发两个恢复任务）；依赖不健康时 上层资源等待（Waiting + waiter 去重），依赖恢复结果共享给全部等待者； 预算/冷却/高风险计数也是中心化状态。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>资源/插件自治恢复</strong>：竞态与顺序错误；重复副作用；无法全局预算控制。</li><li><strong>外部编排器（systemd 依赖）</strong>：systemd 只管服务启动序，不懂健康探针与 验证语义；且把核心逻辑搬出核心。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：单一事实源；等待/唤醒/去重语义集中一处可测试；per-resource 互斥天然防抖。 缺点：中心组件复杂（状态机大）；对引擎实现质量要求高——所以恢复路径有 vertical 集成测试与崩溃恢复测试兜底。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>engine.rs 的 drive/waiters/redrive/finish_* 是核心中最重的路径，改动需带测试。</li><li>插件只能提供能力（动作），不能自作恢复决策（ADR-0015 工具箱模型）。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};